{
  "a_requests": [
    {
      "a_request": "R1",
      "b_asked": "주인 없는 것 같은 강아지 신고처",
      "c_basis": "DIRECT",
      "d_claims": [
        {
          "a_text": "주인 없는 것 같은 강아지는 서울특별시 동물보호 조례상 ‘유기동물’에 해당할 수 있으며, 발견하거나 발견신고를 받은 구청장은 이를 지체 없이 구조·보호할 수 있도록 필요한 조치를 하여야 한다. 따라서 신고는 관할 구청에 하면 된다.",
          "b_ids": "동물보호:제2조제3호, 동물보호:제10조제1항"
        }
      ],
      "e_status": "ANSWERED"
    },
    {
      "a_request": "R2",
      "b_asked": "신고 후 강아지 처리 절차",
      "c_basis": "APPLIED",
      "d_claims": [
        {
          "a_text": "신고로 구조된 유기동물은 동물보호센터에 보호조치되고, 구청장은 동물정보시스템에 공고문을 작성해 7일 이상 공고한다. 등록된 동물이면 소유자에게 즉시 반환하고, 소유자가 반환 요구기간 내에 반환을 요구하면 확인해 확실한 경우 지체 없이 반환한다.",
          "b_ids": "동물보호:제10조제3항, 동물보호:제11조, 동물보호:제16조제1항, 동물보호:제16조제2항"
        },
        {
          "a_text": "공고가 시작된 날부터 10일이 지나도 소유자·관리자가 나타나지 않거나 소유자를 알 수 없으면, 구청장은 해당 동물을 법 제45조 또는 제46조에 따라 처리할 수 있고, 기증·분양 시 중성화 수술에 동의하는 자에게 우선 분양하며 중성화 수술 등을 권고할 수 있다.",
          "b_ids": "동물보호:제16조제3항"
        }
      ],
      "e_status": "ANSWERED"
    }
  ]
}
